\begin{aligned}
\epsilon
&\equiv\epsilon_{\mu_1\cdots\mu_n}
\mathrm dx^{\mu_1}\otimes\cdots\otimes\mathrm dx^{\mu_n}\\
&=\frac1{n!}\epsilon_{\mu_1\cdots\mu_n}
\mathrm dx^{\mu_1}\wedge\cdots\wedge\mathrm dx^{\mu_n}\\
&=\frac1{n!}\sqrt{|g|}\,\widetilde\epsilon_{\mu_1\cdots\mu_n}
\mathrm dx^{\mu_1}\wedge\cdots\wedge\mathrm dx^{\mu_n}\\
&=\sqrt{|g|}\,\mathrm dx^0\wedge\cdots\wedge\mathrm dx^{n-1}\\
&\equiv\sqrt{|g|}\,\mathrm d^nx.
\end{aligned}
\tag{2.96}
